<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { ArrowDown, ArrowUp, Image, LockKeyhole, Plus, RefreshCcw, Save, Sparkles } from 'lucide-vue-next'
import { api } from '../../api'
import StatusPill from '../../components/StatusPill.vue'
import type { Character, Episode, Project, Scene, Shot } from '../../types'
const props = defineProps<{ project: Project; canEdit: boolean; canReview: boolean; eventRevision: number }>()
interface ShotDraft { description: string; action: string; dialogue: string; emotion: string; shot_type: string; camera_angle: string; camera_movement: string; duration: number; prompt: string; negative_prompt: string; character_ids: string[] }
const emptyDraft = (): ShotDraft => ({ description: '', action: '', dialogue: '', emotion: '', shot_type: 'medium', camera_angle: 'eye-level', camera_movement: 'static', duration: 6, prompt: '', negative_prompt: '', character_ids: [] })
const episodes = ref<Episode[]>([]); const episodeId = ref(''); const scenes = ref<Scene[]>([]); const sceneId = ref(''); const shots = ref<Shot[]>([]); const selected = ref<Shot | null>(null); const characters = ref<Character[]>([])
const editing = ref(false); const draft = ref<ShotDraft>(emptyDraft())
const thumbs = ref<Record<string,string>>({}); const builtPrompt = ref(''); const error = ref(''); const notice = ref(''); const busy = ref(false)
const root = computed(() => `/projects/${props.project.id}`)
const total = computed(() => shots.value.reduce((sum, shot) => sum + shot.duration, 0))
async function loadEpisodes() { [episodes.value, characters.value] = await Promise.all([api.get<Episode[]>(`${root.value}/episodes`), api.get<Character[]>(`${root.value}/characters`)]); if (!episodeId.value && episodes.value.length) episodeId.value = episodes.value[0].id; await loadScenes() }
async function loadScenes() { scenes.value = episodeId.value ? await api.get(`${root.value}/episodes/${episodeId.value}/scenes`) : []; if (!scenes.value.some(s => s.id === sceneId.value)) sceneId.value = scenes.value[0]?.id || ''; await loadShots() }
async function loadShots() { shots.value = sceneId.value ? await api.get(`${root.value}/scenes/${sceneId.value}/shots`) : []; if (selected.value) { selected.value = shots.value.find(s => s.id === selected.value?.id) || null; if (selected.value && !editing.value) fillDraft(selected.value) } await loadThumbs() }
async function loadThumbs() { for (const shot of shots.value) { if (shot.current_image_asset_id && !thumbs.value[shot.id]) { try { thumbs.value[shot.id] = await api.blob(`${root.value}/assets/${shot.current_image_asset_id}/content`) } catch {} } } }
function fillDraft(shot: Shot) { draft.value = { description: shot.description, action: shot.action, dialogue: shot.dialogue, emotion: shot.emotion, shot_type: shot.shot_type, camera_angle: shot.camera_angle, camera_movement: shot.camera_movement, duration: shot.duration, prompt: shot.prompt, negative_prompt: shot.negative_prompt, character_ids: [...shot.character_ids] } }
function selectShot(shot: Shot) { selected.value = shot; editing.value = false; fillDraft(shot); builtPrompt.value = '' }
function newShot() { selected.value = null; editing.value = true; draft.value = emptyDraft() }
async function save() { if (!sceneId.value) return; busy.value = true; error.value = ''; try { if (selected.value) { selected.value = await api.patch(`${root.value}/shots/${selected.value.id}`, { ...draft.value, expected_version: selected.value.version }); notice.value = '镜头已保存。' } else { selected.value = await api.post(`${root.value}/scenes/${sceneId.value}/shots`, draft.value); notice.value = '镜头已创建。' } editing.value = false; await loadShots() } catch (cause) { error.value = (cause as Error).message } finally { busy.value = false } }
async function transition(target: string) { if (!selected.value) return; try { selected.value = await api.post(`${root.value}/shots/${selected.value.id}/transition`, { expected_version: selected.value.version, target }); await loadShots(); notice.value = `镜头已进入 ${target}。` } catch (cause) { error.value = (cause as Error).message } }
async function generate(kind: string) { if (!selected.value) return; busy.value = true; try { await api.post(`${root.value}/shots/${selected.value.id}/generations`, { kind, idempotency_key: crypto.randomUUID() }); await loadShots(); notice.value = `${kind} 任务已加入队列。` } catch (cause) { error.value = (cause as Error).message } finally { busy.value = false } }
async function reorder(delta: number) { if (!selected.value) return; try { selected.value = await api.post(`${root.value}/shots/${selected.value.id}/reorder`, { expected_version: selected.value.version, target_no: selected.value.shot_no + delta }); await loadShots() } catch (cause) { error.value = (cause as Error).message } }
async function previewPrompt() { if (!selected.value) return; const result = await api.get<{prompt:string}>(`${root.value}/shots/${selected.value.id}/built-prompt`); builtPrompt.value = result.prompt }
watch(() => props.eventRevision, loadShots); onMounted(loadEpisodes); onBeforeUnmount(() => Object.values(thumbs.value).forEach(URL.revokeObjectURL))
</script>
<template>
  <div class="section-head"><div><div class="section-kicker">Storyboard Studio</div><h1>分镜工作室</h1><p>场景、镜头画板、参数检查器与时间线预览集中在同一工作台。</p></div><div class="toolbar"><select v-model="episodeId" style="width:200px" aria-label="选择剧集" @change="loadScenes"><option v-for="episode in episodes" :key="episode.id" :value="episode.id">EP {{ episode.episode_no }} · {{ episode.title }}</option></select><button class="btn" @click="loadShots"><RefreshCcw :size="15" />刷新</button></div></div>
  <div v-if="error" class="error" style="margin-bottom:16px">{{ error }}</div><div v-if="notice" class="notice" style="margin-bottom:16px">{{ notice }}</div>
  <div style="display:grid;grid-template-columns:190px minmax(0,1fr) 310px;gap:15px" class="storyboard-layout">
    <section class="panel panel-pad" style="padding:15px"><div class="between"><h3 style="margin:0">场景</h3><span class="mini-label">{{ scenes.length }}</span></div><div class="list" style="margin-top:14px"><button v-for="scene in scenes" :key="scene.id" class="scene-row" :class="{active:sceneId === scene.id}" style="color:inherit;text-align:left" @click="sceneId = scene.id; selected = null; loadShots()"><span class="mini-label">{{ String(scene.scene_no).padStart(2,'0') }}</span><span style="font-size:12px">{{ scene.heading }}</span></button></div><div v-if="!scenes.length" class="empty" style="min-height:160px;padding:20px"><div><strong>暂无场景</strong><p>先在剧集页面添加场景。</p></div></div></section>
    <section class="panel panel-pad"><div class="between" style="margin-bottom:18px"><div><h2 style="margin-bottom:4px">镜头画板</h2><small>{{ shots.length }} 个镜头 · {{ total }} 秒</small></div><button v-if="canEdit && sceneId" class="btn btn-primary" @click="newShot"><Plus :size="15" />创建镜头</button></div><div v-if="shots.length" class="shot-grid"><button v-for="shot in shots" :key="shot.id" class="shot-card" :class="{active:selected?.id === shot.id}" style="text-align:left;color:inherit" @click="selectShot(shot)"><div class="shot-thumb"><img v-if="thumbs[shot.id]" :src="thumbs[shot.id]" alt="镜头生成图" /><Image v-else :size="28" /></div><div class="shot-info"><div class="between"><strong>Shot {{ String(shot.shot_no).padStart(2,'0') }}</strong><StatusPill :status="shot.status" /></div><p>{{ shot.description || '未填写描述' }}</p></div></button></div><div v-else class="empty"><div><strong>还没有镜头</strong><p>选择场景并创建第一个镜头。</p></div></div></section>
    <aside class="inspector"><div class="between"><h3>{{ selected ? `Shot ${String(selected.shot_no).padStart(2,'0')} 检查器` : '新镜头' }}</h3><StatusPill v-if="selected" :status="selected.status" /></div><template v-if="selected || editing"><div class="grid-two"><div class="field"><label>景别</label><input v-model="draft.shot_type" :disabled="!canEdit || selected?.status === 'LOCKED'" /></div><div class="field"><label for="shot-duration">时长（秒）</label><input id="shot-duration" v-model.number="draft.duration" type="number" min="1" max="30" :disabled="!canEdit || selected?.status === 'LOCKED'" /></div></div><div class="field"><label>机位角度</label><input v-model="draft.camera_angle" :disabled="!canEdit || selected?.status === 'LOCKED'" /></div><div class="field"><label>镜头运动</label><input v-model="draft.camera_movement" :disabled="!canEdit || selected?.status === 'LOCKED'" /></div><div class="field"><label>出镜角色（可多选）</label><select v-model="draft.character_ids" multiple aria-label="出镜角色" :disabled="!canEdit || selected?.status === 'LOCKED'" style="min-height:96px"><option v-for="character in characters" :key="character.id" :value="character.id">{{ character.name }}{{ character.active_version_id ? '' : '（未激活版本）' }}</option></select><small class="muted">生成时会读取已激活角色版本的 DNA；未激活角色不会提供正式锚点。</small></div><div class="field"><label for="shot-description">画面描述</label><textarea id="shot-description" v-model="draft.description" rows="3" :disabled="!canEdit || selected?.status === 'LOCKED'"></textarea></div><div class="field"><label>动作</label><textarea v-model="draft.action" rows="2" :disabled="!canEdit || selected?.status === 'LOCKED'"></textarea></div><div class="field"><label for="shot-dialogue">对白</label><textarea id="shot-dialogue" v-model="draft.dialogue" rows="2" :disabled="!canEdit || selected?.status === 'LOCKED'"></textarea></div><div class="field"><label>Prompt</label><textarea v-model="draft.prompt" rows="2" :disabled="!canEdit || selected?.status === 'LOCKED'"></textarea></div><button v-if="canEdit && selected?.status !== 'LOCKED'" class="btn btn-primary" :disabled="busy" @click="save"><Save :size="15" />保存镜头</button><div v-if="selected" class="divider"></div><div v-if="selected" class="toolbar"><button v-if="canEdit && selected.status === 'DRAFT'" class="btn btn-sm" @click="transition('PLANNED')">规划完成</button><button v-if="canEdit && selected.status === 'PLANNED'" class="btn btn-sm" @click="transition('STORYBOARD_READY')">分镜就绪</button><button v-if="canEdit && selected.status === 'REJECTED'" class="btn btn-sm" @click="transition('PLANNED')">重新规划</button><button v-if="canEdit && selected.status === 'FAILED'" class="btn btn-sm" @click="transition('STORYBOARD_READY')">恢复生成</button><button v-if="canReview && selected.status === 'REVIEW_REQUIRED' && selected.inspection_json?.status !== 'FAIL'" class="btn btn-sm btn-primary" @click="transition('APPROVED')">通过审核</button><button v-if="canReview && selected.status === 'APPROVED'" class="btn btn-sm" @click="transition('LOCKED')"><LockKeyhole :size="13" />锁定</button><button v-if="canEdit && ['STORYBOARD_READY','REVIEW_REQUIRED'].includes(selected.status)" class="btn btn-sm" :disabled="busy" @click="generate('IMAGE')"><Sparkles :size="13" />生成图像</button><button v-if="canEdit && selected.current_image_asset_id && selected.status === 'REVIEW_REQUIRED'" class="btn btn-sm" :disabled="busy" @click="generate('VIDEO')">生成视频</button><button v-if="canEdit && selected.dialogue && selected.status === 'REVIEW_REQUIRED'" class="btn btn-sm" :disabled="busy" @click="generate('VOICE')">生成配音</button><button class="btn btn-sm" @click="previewPrompt">预览提示词</button><button v-if="canEdit && selected.shot_no > 1" class="icon-button" title="上移" @click="reorder(-1)"><ArrowUp :size="14" /></button><button v-if="canEdit && selected.shot_no < shots.length" class="icon-button" title="下移" @click="reorder(1)"><ArrowDown :size="14" /></button></div><p v-if="builtPrompt" class="story-text subtle-panel" style="padding:12px;margin-top:12px">{{ builtPrompt }}</p></template><div v-else class="empty" style="min-height:300px"><div><strong>选择镜头</strong><p>查看参数、生成素材或推进审核。</p></div></div></aside>
  </div>
  <section class="panel panel-pad" style="margin-top:16px"><div class="between"><h3 style="margin:0">时间线预览</h3><small>{{ total }} 秒</small></div><div class="timeline-strip" style="margin-top:13px"><div v-for="shot in shots" :key="shot.id" class="timeline-clip" :style="{width:`${Math.max(100,shot.duration*20)}px`}"><strong>{{ String(shot.shot_no).padStart(2,'0') }}</strong><br>{{ shot.duration }}s · {{ shot.status }}</div><small v-if="!shots.length">镜头出现后将显示在这里。</small></div></section>
</template>
<style scoped>@media(max-width:1350px){.storyboard-layout{grid-template-columns:160px minmax(0,1fr)!important}.storyboard-layout .inspector{grid-column:1/-1}}@media(max-width:760px){.storyboard-layout{display:flex!important;flex-direction:column}}</style>
